const data = require('fs').readFileSync(0, 'utf8').split(/\s+/).filter(x=>x.length>0).map(Number);
const p = data[0], s = data[1], r = data[2];
const MOD = 998244353;

function mul(a, b) {
  const ah = Math.floor(a / 65536), al = a % 65536;
  return ((ah * b % MOD) * 65536 + al * b) % MOD;
}
function power(a, e) {
  let res = 1; a %= MOD;
  while (e > 0) {
    if (e & 1) res = mul(res, a);
    a = mul(a, a);
    e = Math.floor(e / 2);
  }
  return res;
}
function inv(a) { return power(a, MOD - 2); }

const MAXN = s + p + 10;
const fact = new Array(MAXN), invfact = new Array(MAXN);
fact[0] = 1;
for (let i = 1; i < MAXN; i++) fact[i] = mul(fact[i-1], i);
invfact[MAXN-1] = inv(fact[MAXN-1]);
for (let i = MAXN-1; i > 0; i--) invfact[i-1] = mul(invfact[i], i);

function C(n, k) {
  if (k < 0 || n < 0 || k > n) return 0;
  return mul(fact[n], mul(invfact[k], invfact[n-k]));
}

// inverses of 1..p
const invs = new Array(p + 2);
for (let i = 1; i <= p + 1; i++) invs[i] = inv(i);

const total = C(s - r + p - 1, p - 1);

let ans = 0;
for (let m = r; m <= s; m++) {
  for (let k = 0; k <= p - 1; k++) {
    const rem = s - m * (k + 1);
    if (rem < 0) break;
    const n = p - 1 - k;
    let cnt = 0;
    if (n === 0) {
      cnt = (rem === 0) ? 1 : 0;
    } else {
      if (m === 0) {
        cnt = 0;
      } else {
        const jmax = Math.min(n, Math.floor(rem / m));
        let acc = 0;
        for (let j = 0; j <= jmax; j++) {
          const term = mul(C(n, j), C(rem - j * m + n - 1, n - 1));
          if (j % 2 === 0) acc = (acc + term) % MOD;
          else acc = (acc - term + MOD) % MOD;
        }
        cnt = acc;
      }
    }
    if (cnt === 0) continue;
    let contrib = mul(C(p - 1, k), mul(cnt, invs[k + 1]));
    ans = (ans + contrib) % MOD;
  }
}

const res = mul(ans, inv(total));
console.log(res.toString());
